WeatherRequest.body:
try {
  const request = await fetch(`https://api.open-meteo.com/v1/forecast?latitude=55.75&longitude=37.62&current_weather=true&hourly=temperature_2m,relativehumidity_2m,windspeed_10m`, {signal: AbortSignal.timeout(10000)})
  const value = await request.json()    
  e.setUserDefinedProps({children: `Current weather is ${value.current_weather.temperature} °C`})
} catch (error) {
  e.setUserDefinedProps({children: `Current weather is not available`})
}
